import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Installer et gérer les plugins","description":"","frontmatter":{"title":"Installer et gérer les plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"e7902639e11eaa32139763ad0821b1493f0ce5a9dd26f8a307b287d642fa47fa","order":10},"headers":[],"relativePath":"fr/user/plugins/index.md","filePath":"fr/user/plugins/index.md","lastUpdated":1795735295000}`),s={name:`fr/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">Installer et gérer les plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “Installer et gérer les plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Ajouter une intégration, examiner les accès demandés et confirmer que ses actions sont utilisables. Il faut un paquet de bureau compatible avec le système d’exploitation, l’architecture et la version d’hôte du plugin. Les opérations de catalogue distant et de téléchargement nécessitent un accès réseau ; certains services liés au compte nécessitent aussi une <a href="./../cloud/account.html">connexion Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Examiner avant d’activer <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “Examiner avant d’activer”">​</a></h2><ol><li>Ouvrez <strong>Plugins</strong> et examinez Installed, Explore ou Updates. Explore demande uniquement des entrées de plugins. Les modèles et profils d’automatisation se trouvent dans <a href="./../automations/templates.html">Automations</a>.</li><li>Sélectionnez un plugin pour examiner sa description, sa version, sa compatibilité et son environnement d’exécution. Vérifiez l’éditeur et les capacités ou permissions demandées plutôt que de vous fier uniquement à un nom familier.</li><li>Utilisez le parcours d’installation pour examiner l’aperçu du paquet. Examinez la version exacte, les informations de signature, les accès demandés et les différences avec une version installée avant de confirmer l’installation.</li><li>Attendez le résultat de la tâche de paquet. Téléchargement, installation et activation sont des étapes distinctes ; une fiche de catalogue seule ne signifie pas que l’environnement d’exécution est prêt.</li><li>Ouvrez le volet Settings ou Connection du plugin. Fournissez l’adresse de son service et ses identifiants uniquement dans les champs prévus. Utilisez la vérification de connexion déclarée lorsqu’elle est proposée.</li><li>Activez le plugin, puis vérifiez l’apparition de ses types d’action ou pages. Créez une <a href="./../automations/first-rule.html">règle de journalisation</a> ciblée avant d’attacher une action externe puissante.</li></ol><p>Les plugins peuvent exécuter du code natif ou des processus séparés. Une frontière de processus peut isoler un plantage, mais ne constitue pas un bac à sable du système d’exploitation. Installez des logiciels provenant d’éditeurs de confiance. Une signature valide identifie la provenance vérifiée d’un paquet ; elle ne rend pas chaque effet approprié à votre usage.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et état”">​</a></h2><p>L’examen des paquets, les tâches d’installation, les préférences de plugins et la gestion des versions sont disponibles. Les actions réelles dépendent du manifeste installé, des capacités de l’hôte et du service externe. Les processeurs d’événements ont leur propre panneau et peuvent ajouter des champs d’analyse facultatifs aux événements ; les champs bruts restent distincts.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>En cas d’échec d’installation, lisez l’erreur de tâche pour identifier un problème de compatibilité, signature, exécution ou téléchargement. N’affaiblissez pas la vérification simplement pour effacer l’erreur. Si une mise à jour pose problème, examinez les versions conservées et utilisez le retour arrière lorsqu’il est disponible. Examinez les automatisations dépendantes avant de désactiver ou désinstaller un plugin. Gardez des <a href="./../preferences/backups.html">sauvegardes</a> des données et configurations des plugins avant de les supprimer.</p>`,10),t(d,{id:`plugin`,locale:`fr`,title:`Démo : plugins`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>lister les plugins installés</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>lire un plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>installer depuis un fichier, id@version ou url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>désinstaller un plugin <strong>destructif</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>rechercher des paquets dans le registre</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspecter une spécification de paquet avant installation</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>lister les plugins installés avec des mises à jour disponibles</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>mettre à jour un plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>mettre à jour tous les plugins obsolètes</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>revenir à une version précédente <strong>destructif</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>lister les versions disponibles d&#39;un plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>épingler un plugin à sa version actuelle</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>retirer l&#39;épinglage de version</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>définir le canal et la politique de mise à jour automatique</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>lister les travaux de paquets</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspecter un travail de paquet</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>annuler un travail de paquet en cours <strong>destructif</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>activer un plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>désactiver un plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>démarrer un plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>arrêter un plugin <strong>destructif</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>lire la configuration d&#39;un plugin</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>écrire la configuration d&#39;un plugin</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>réinitialiser la configuration d&#39;un plugin <strong>destructif</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>vérification de santé d&#39;un plugin</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>options d&#39;un type d&#39;action ou champ</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>exécuter une action de plugin</td></tr><tr><td><code>tiktools plugin commands</code></td><td>lister les commandes contribuées par les plugins installés</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>décrire une commande contribuée</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invoquer une commande contribuée par un plugin</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>lister les registres configurés</td></tr><tr><td><code>tiktools registry refresh</code></td><td>actualiser les métadonnées du registre</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>afficher un paquet du registre</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>rechercher dans le catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>page de résumés du catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versions d&#39;un paquet du catalogue cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacités de pagination du catalogue cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuration par défaut du registre</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>lister les processeurs</td></tr><tr><td><code>tiktools processor status</code></td><td>état du pipeline de processeurs</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>exécuter un processeur contre un événement d&#39;exemple</td></tr></tbody></table><p>Consultez la <a href="./../../developer/cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};